	\begin{axis}[
	%axis on top=true,
	tick style={draw=none},
	tick label style={font=\scriptsize},
	label style={font=\small},
	tick style={draw=black, thick},
	minor tick style={draw=none},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	axis equal, 
	grid = both, grid style={opacity=0.5},
	xmin = -2.5, xmax = 2.5,
	ymin = -2.5, ymax = 2.5,
	xtick = {-2,2}, ytick = {-2,2},
	minor xtick={-7,-6,...,7}, minor ytick={-7,-6,...,7},
	%% Here, we can control the positioning of each individual tick.
	x tick label style={xshift={(\tick==-2)*-6pt}},		
	x tick label style={xshift={(\tick==2)*6pt}},		
	y tick label style={yshift={(\tick==-2)*-6pt}},		
    y tick label style={yshift={(\tick==2)*6pt}},		
	%xticklabels={,,}, %yticklabels={,,},
	xlabel = {$x$}, ylabel = {$y$},
	xlabel style={below right}, ylabel style={above right},
	every axis x label/.style={at={(ticklabel* cs:1.02)}, anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

	\def\A 
	{
		plot[domain=-0:360, samples=100] 
		(axis cs: {2*cos(\x)}, {2*sin(\x)});
		% Ancors:
		% (current page.north east) 
		% (current page.south east) 
		% (current page.south west) 
		% (current page.north west) 
	}


	\begin{scope}
	\fill[fill style] \A;
	\end{scope}
	\draw[exclude style] \A;
	%\node[] at (axis cs:3,2.7) {\small $\displaystyle \frac{x^2}{9}+\frac{y^2}{4}=1$};


	\end{axis}
	\end{tikzpicture}
\end{document}

